# Test pattern replacement for value 4
def transform(grid, target_val, pattern=[6, 2, 2, 6, 6]):
    result = []
    for row in grid:
        new_row = []
        for val in row:
            if val == target_val:
                new_row.extend(pattern)
            else:
                new_row.append(val)
        result.append(new_row)
    return result

