from collections import deque

def find_components(grid, bg):
    """Find all connected regions of non-bg values"""
    visited = set()
    components = []

    def bfs(start, val):
        comp = []
        q = deque([start])
        visited.add(start)
        while q:
            r, c = q.popleft()
            comp.append((r, c))
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if grid[nr][nc] != bg and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        q.append((nr, nc))
        return sorted(comp)

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val != bg and (r,c) not in visited:
                comps = bfs((r,c), val)
                components.append(comps)
    return components

